\section{Introduction}

\subsection{The dollar game and its rank}

Divisor theory on finite graphs, initiated by Baker and Norine \cite{BN}, transplants the
language of algebraic curves onto combinatorics.  A \emph{divisor} on a graph $G=(V,E)$
is an element $D\in\ZZ^V$; one thinks of $D(v)$ as a number of chips (possibly negative,
i.e.\ debt) held at $v$.  The \emph{degree} is $\deg D=\sum_v D(v)$, and $D$ is
\emph{effective} if $D(v)\ge 0$ for all $v$.

The dynamics come from \emph{chip firing}: a vertex $v$ fires by sending one chip along
each incident edge.  If $f\in\ZZ^V$ records the number of times each vertex fires, the
net effect on $D$ is the addition of $Lf$, where $L$ is the graph Laplacian,
\[
  (Lf)(v)\;=\;\deg_G(v)\,f(v)\;-\;\sum_{u\sim v}f(u).
\]
Two divisors $D,D'$ are \emph{linearly equivalent}, $D\sim D'$, if $D'=D+Lf$ for some
$f$.  The \emph{dollar game} \cite{Biggs} asks whether a given $D$ is linearly equivalent
to an effective divisor.

Baker and Norine refined this binary question into a numerical invariant, the
\emph{rank}:
\[
  r(D)\;=\;\max\bigl\{\,r\in\ZZ_{\ge 0}\;:\;\text{for every effective }E\text{ with }
  \deg E=r,\ D-E\sim\text{effective}\,\bigr\},
\]
with the convention $r(D)=-1$ if $D$ itself is not equivalent to an effective divisor.
Equivalently, $r(D)\ge r$ means that the configuration survives the adversarial removal
of any $r$ chips.

With the \emph{genus} $g=|E|-|V|+1$ and the \emph{canonical divisor}
$K_G(v)=\deg_G(v)-2$, of degree $2g-2$, the central structural theorem is the
graph-theoretic Riemann--Roch theorem \cite{BN}:
\[
  r(D)-r(K_G-D)\;=\;\deg D-g+1 .
\]

Ranks are hard to compute: deciding whether $r(D)\ge r$ is NP-hard for general graphs
\cite{KT}.  Explicit rank formulas for infinite families are therefore rare, and formulas
for families of \emph{unbounded} rank rarer still.

\subsection{The problem and the result}

This paper computes exactly the rank of the most symmetric divisor on the most symmetric
graph.

\begin{theorem}[Main Theorem; see Theorem~\ref{thm:main}]
Let $m\ge 0$ and $n\ge m+2$.  On the complete graph $K_n$, the uniform divisor
$m\cdot\one$, with $m$ chips at every vertex, has Baker--Norine rank exactly
\[
  r(m\cdot\one)\;=\;\frac{m(m+3)}{2}.
\]
\end{theorem}

Three features deserve emphasis.

\begin{enumerate}
\item \textbf{Independence of $n$.}  The rank does not depend on the size of the graph,
only on $m$.  This is not visible from Riemann--Roch: the bound $r(D)\ge \deg D-g$ reads
$mn-\binom{n-1}{2}$, which is negative for large $n$.
\item \textbf{Quadratic growth.}  Prior general lower bounds for uniform divisors on
graphs of minimum degree $k$ were linear in $m$: a one-shot set-firing estimate gives
$\min(3m-1,k+m)$, and a refinement using an optimally chosen threshold set gives
$2m+\lfloor m^2/4\rfloor$, still bounded by the cap $k+m$.  On $K_n$ with $n$ large the
truth is quadratic and unbounded in $m$, and for $m\ge 3$ strictly exceeds
$2m+\lfloor m^2/4\rfloor$.  Hence no single firing move can prove the theorem; a whole
coordinated firing vector is required.
\item \textbf{Extremality.}  For odd $n=2m+3$, the divisor $m\cdot\one$ is a theta
characteristic of degree exactly $g-1$; its rank satisfies $4r>g$.  Brill--Noether
heuristics predict rank at most about $\sqrt{g}$ at degree $g-1$; the complete graph
beats this by an order of magnitude.
\end{enumerate}

\subsection{Method}

The complete graph makes the Laplacian degenerate in a very useful way:
$(Lf)(v)=nf(v)-\sum_u f(u)$ on $K_n$.  Each coordinate depends on $f(v)$ and on the
single scalar $\sum_u f(u)$.  Consequently the dollar game on $K_n$ is equivalent to a
one-parameter integer optimisation:
\[
  D\sim\text{effective}\iff \exists\, s\in\ZZ:\ \sum_v\Bigl\lceil\frac{s-D(v)}{n}
  \Bigr\rceil\le s .
\]
Every result in this paper is a consequence of this criterion.

\section{Preliminaries}

Throughout, $G=(V,E)$ is a finite, simple, connected graph with $|V|=n$.

\begin{definition}
A \emph{divisor} on $G$ is a function $D:V\to\ZZ$; these form the free abelian group
$\Div(G)\cong\ZZ^V$.  Its \emph{degree} is $\deg D=\sum_{v\in V}D(v)$.  We write $D\ge 0$
and call $D$ \emph{effective} when $D(v)\ge0$ for all $v$.
\end{definition}

\begin{definition}
For $f:V\to\ZZ$ set $(Lf)(v)=\deg_G(v)f(v)-\sum_{u\sim v}f(u)$; then $\deg(Lf)=0$.  Write
$D\sim D'$ iff $D'-D=Lf$ for some $f$.  Since $G$ is connected, $Lf=0$ iff $f$ is
constant.
\end{definition}

\begin{definition}
For $r\in\ZZ_{\ge0}$ we say $r(D)\ge r$ if for every effective $E$ with $\deg E=r$ there
is $f$ with $D-E+Lf\ge0$.  The \emph{Baker--Norine rank} $r(D)$ is the largest such $r$,
or $-1$ if $D$ is equivalent to no effective divisor.  The predicate is antitone in $r$,
and $r(D)$ depends only on the class of $D$.
\end{definition}

\begin{definition}
$g(G)=|E|-|V|+1$ is the \emph{genus} and $K_G(v)=\deg_G(v)-2$ the \emph{canonical
divisor}; $\deg K_G=2g-2$.
\end{definition}

\begin{theorem}[Riemann--Roch for graphs \cite{BN}]\label{thm:RR}
For every divisor $D$ on a connected graph $G$,
$r(D)-r(K_G-D)=\deg D-g+1$.
\end{theorem}

\begin{definition}
A divisor $D$ is a \emph{theta characteristic} if $2D\sim K_G$.  Every theta
characteristic has degree $g-1$ and is a fixed point of the residual involution
$D\mapsto K_G-D$ on classes of degree $g-1$.  By Theorem~\ref{thm:RR} that involution
preserves rank, so extremal behaviour at the \emph{half-canonical degree} $g-1$ is
naturally studied through these fixed classes.
\end{definition}

\begin{notation}
$K_n$ is the complete graph on $\{v_1,\dots,v_n\}$; it is $(n-1)$-regular with
$\binom n2$ edges,
\[
  g(K_n)=\frac{(n-1)(n-2)}{2},\qquad K_{K_n}=(n-3)\cdot\one ,
\]
where $c\cdot\one$ is the constant divisor with value $c$.  We write
$\lceil x\rceil_+=\max(\lceil x\rceil,0)$ and use $\lceil a/n\rceil=\lfloor
(a+n-1)/n\rfloor$ for integers $a$ and $n\ge1$.
\end{notation}

\section{The effectivity criterion on a complete graph}

\begin{lemma}[Collapse of the Laplacian]\label{lem:lap}
On $K_n$, for every $f:V\to\ZZ$ and every $v$, $(Lf)(v)=n\,f(v)-\sum_u f(u)$.
\end{lemma}

\begin{proof}
$\deg_{K_n}(v)=n-1$ and $\sum_{u\sim v}f(u)=\sum_u f(u)-f(v)$, so
$(Lf)(v)=(n-1)f(v)-\bigl(\sum_uf(u)-f(v)\bigr)=nf(v)-\sum_uf(u)$.
\end{proof}

\begin{theorem}[Effectivity criterion]\label{thm:crit}
Let $n\ge1$ and let $D$ be a divisor on $K_n$.  Then
\[
  \bigl(\exists f:\ D+Lf\ge0\bigr)\iff
  \Bigl(\exists s\in\ZZ:\ \sum_v\Bigl\lceil\frac{s-D(v)}{n}\Bigr\rceil\le s\Bigr).
\]
\end{theorem}

\begin{proof}
($\Rightarrow$) Suppose $D+Lf\ge0$ and set $s:=\sum_u f(u)$.  By Lemma~\ref{lem:lap},
$D(v)+nf(v)-s\ge0$, i.e.\ $f(v)\ge (s-D(v))/n$; as $f(v)\in\ZZ$ this gives
$f(v)\ge\lceil (s-D(v))/n\rceil$, and summing over $v$ yields
$s=\sum_v f(v)\ge\sum_v\lceil (s-D(v))/n\rceil$.

($\Leftarrow$) Given such an $s$, put $f(v):=\lceil (s-D(v))/n\rceil$ and
$S:=\sum_vf(v)\le s$.  By definition of the ceiling, $nf(v)\ge s-D(v)$, so
\[
  (D+Lf)(v)=D(v)+nf(v)-S\ \ge\ D(v)+\bigl(s-D(v)\bigr)-S\ =\ s-S\ \ge\ 0. \qedhere
\]
\end{proof}

The converse direction is constructive: the shift $s$ \emph{is} the winning strategy.

\begin{definition}
For a divisor $D$ on $K_n$ set
\[
  \varphi_D(s)=\sum_v\Bigl\lceil\frac{s-D(v)}{n}\Bigr\rceil-s,
  \qquad d(D)=\min_{s\in\ZZ}\varphi_D(s),
\]
the \emph{deficiency} of $D$.  By Theorem~\ref{thm:crit}, $D\sim$ effective iff
$d(D)\le0$.
\end{definition}

\begin{lemma}[Periodicity]\label{lem:per}
$\varphi_D(s+n)=\varphi_D(s)$ for all $s$, and
\[
  \varphi_D(s+1)-\varphi_D(s)=\#\{v: D(v)\equiv s \ (\mathrm{mod}\ n)\}-1 .
\]
In particular $d(D)$ is the minimum of $\varphi_D$ over any $n$ consecutive integers.
\end{lemma}

\begin{proof}
For integers $a$, $\lceil (a+n)/n\rceil=\lceil a/n\rceil+1$; summing over $v$ and
accounting for the $-s$ term gives $\varphi_D(s+n)=\varphi_D(s)+n-n=\varphi_D(s)$.  For
the increment, $\lceil (s+1-D(v))/n\rceil-\lceil (s-D(v))/n\rceil$ is $1$ if
$n\mid(s-D(v))$ and $0$ otherwise; subtracting the increment $1$ of the $-s$ term gives
the formula.  Summing the increments over one period recovers $n-n=0$.
\end{proof}

\begin{remark}
Lemma~\ref{lem:per} shows $\varphi_D$ is a cyclic prefix-sum profile determined by the
multiset of residues $D(v)\bmod n$ together with one base value.  This gives an $O(n)$
algorithm for the dollar game on $K_n$ (Section~\ref{sec:alg}), a striking contrast with
NP-hardness in general \cite{KT}.
\end{remark}

\begin{example}
On $K_4$ take $D=(-1,0,1,2)$.  The residues mod $4$ are $3,0,1,2$, one in each class, so
$\varphi_D$ is constant; at $s=2$ it equals $1+1+1+0-2=1$.  Hence $d(D)=1>0$ and the
configuration can never be rescued.  Adding a single chip, $D'=(-1,0,1,3)$, gives
$d(D')=0$.
\end{example}

\section{Riemann's inequality on a complete graph}

\begin{lemma}[Ceiling as a floor]\label{lem:cf}
For integers $y$ and $n\ge1$, $-\lfloor y/n\rfloor=\lfloor(-y+n-1)/n\rfloor$.
\end{lemma}

\begin{proof}
Write $y=nq+t$ with $0\le t<n$.  Then $-y+n-1=(n-1-t)+n(-q)$ with $0\le n-1-t<n$, so the
right-hand side is $-q$.
\end{proof}

\begin{lemma}[Hermite's identity]\label{lem:herm}
For every integer $z$ and $n\ge1$, $\displaystyle\sum_{s=0}^{n-1}
\Bigl\lfloor\frac{z+s}{n}\Bigr\rfloor=z$.
\end{lemma}

\begin{proof}
Write $z=nq+t$, $0\le t<n$.  For $0\le s<n$, $\lfloor (z+s)/n\rfloor=q+\lfloor
(t+s)/n\rfloor$, and $\lfloor (t+s)/n\rfloor$ is $1$ exactly when $s\ge n-t$.  There are
$t$ such $s$, so the sum is $nq+t=z$.
\end{proof}

\begin{theorem}[Riemann's inequality on $K_n$]\label{thm:riemann}
Let $n\ge1$ and let $D$ be a divisor on $K_n$ with $\deg D\ge g(K_n)$.  Then $D$ is
linearly equivalent to an effective divisor.
\end{theorem}

\begin{proof}
Suppose not.  By Theorem~\ref{thm:crit}, for every $s$ we have
$\sum_v\lceil (s-D(v))/n\rceil\ge s+1$.  Apply this for $s=0,\dots,n-1$ and sum; the left
side is $n(n+1)/2$.  For the right side, Lemma~\ref{lem:cf} with $y=D(v)-s$ gives
\[
  \Bigl\lceil\frac{s-D(v)}{n}\Bigr\rceil
  =-\Bigl\lfloor\frac{D(v)-s}{n}\Bigr\rfloor
  =\Bigl\lfloor\frac{(-D(v)+n-1)+s}{n}\Bigr\rfloor,
\]
so exchanging the order of summation and applying Lemma~\ref{lem:herm} with
$z=-D(v)+n-1$ for each $v$ turns the right side into
$\sum_v(-D(v)+n-1)=-\deg D+n(n-1)$.  Hence $n(n+1)/2\le n(n-1)-\deg D$, i.e.
\[
  \deg D\le n(n-1)-\frac{n(n+1)}{2}=\frac{n(n-3)}{2}=g-1,
\]
contradicting $\deg D\ge g$.
\end{proof}

\begin{corollary}\label{cor:riemann}
If $\deg D\ge g+r$ with $r\ge0$, then $r(D)\ge r$ on $K_n$.
\end{corollary}

\begin{definition}[Staircase divisor]\label{def:stair}
For $n\ge m+2$ let
\[
  S_{n,m}=\bigl(-1,\ 0,\ 1,\ 2,\ \dots,\ m,\ \underbrace{m,\dots,m}_{n-m-2}\bigr)\in\ZZ^n,
\]
i.e.\ $S_{n,m}(v_1)=-1$, $S_{n,m}(v_i)=i-2$ for $2\le i\le m+2$, and $S_{n,m}(v_i)=m$ for
$i>m+2$.  Its degree is
$\deg S_{n,m}=-1+\tfrac{m(m+1)}{2}+(n-m-2)m=mn-\tfrac{m(m+3)}{2}-1$.
\end{definition}

\begin{proposition}[The staircase is stuck]\label{prop:stuck}
For $n\ge m+2$ one has $d(S_{n,m})=1$; in particular $S_{n,m}$ is not linearly equivalent
to any effective divisor.
\end{proposition}

\begin{proof}
Write $S=S_{n,m}$; all values lie in $[-1,m]$ with $m\le n-2$.  Take the window
$s\in\{-1,0,\dots,n-2\}$, a complete residue system mod $n$ (Lemma~\ref{lem:per}).  For
such $s$ and any $v$ we have $s-S(v)\in(-n,n]$, so $\lceil (s-S(v))/n\rceil$ is $1$ if
$S(v)<s$ and $0$ otherwise; hence $\varphi_S(s)=\#\{v:S(v)<s\}-s$.  Now:
$\varphi_S(-1)=0-(-1)=1$; for $0\le s\le m$ the values below $s$ are $-1$ and
$0,\dots,s-1$, i.e.\ $s+1$ of them, so $\varphi_S(s)=1$; for $m+1\le s\le n-2$ all $n$
values are below $s$, so $\varphi_S(s)=n-s\ge2$.  Thus $\min\varphi_S=1>0$.
\end{proof}

\begin{corollary}[Sharpness]\label{cor:sharp}
Taking $m=n-2$, the divisor $S_{n,n-2}=(-1,0,1,\dots,n-2)$ has degree exactly $g-1$ and
is not equivalent to an effective divisor.  So the hypothesis $\deg D\ge g$ in
Theorem~\ref{thm:riemann} cannot be weakened.
\end{corollary}

\section{Ceiling weights and a counting identity}

Fix $n\ge1$.

\begin{definition}
For $a,j\in\ZZ_{\ge0}$ put $w(a,j)=\lceil (a-j)/n\rceil_+$.
\end{definition}

\begin{lemma}\label{lem:defprop}
$a\le j+n\,w(a,j)$ for all $a,j\ge0$.
\end{lemma}

\begin{lemma}\label{lem:anti}
If $j\le j'$ then $w(a,j')\le w(a,j)$.
\end{lemma}

\begin{lemma}[Exact value]\label{lem:wtval}
If $0\le j<n$ and $a=nQ+R$ with $0\le R<n$, then $w(a,j)=Q+[\,j<R\,]$.
\end{lemma}

\begin{proof}
If $j<R$ then $a-j=nQ+(R-j)$ with $0<R-j\le n-1$, giving $Q+1$.  If $j\ge R$ and $Q\ge1$
then $a-j=n(Q-1)+(R+n-j)$ with $0<R+n-j\le n$, giving $Q$.  If $j\ge R$ and $Q=0$ then
$a=R\le j$ and the truncated value is $0=Q$.
\end{proof}

\begin{proposition}[Counting identity]\label{prop:count}
For $m\le n$ and $a=nQ+R$ with $0\le R<n$,
\[
  \sum_{j=0}^{m-1}w(a,j)=mQ+\min(m,R).
\]
\end{proposition}

\begin{corollary}\label{cor:count}
If $m+2\le n$ then $\sum_{j<m}w(a,j)\le a$ for every $a\ge0$, with strict inequality
whenever $a\ge m+1$.
\end{corollary}

\begin{proof}
$mQ+\min(m,R)\le nQ+R=a$ since $m\le n$.  For strictness with $a\ge m+1$: if $Q=0$ then
$a=R$ and the sum is $\min(m,a)=m\le a-1$; if $Q\ge1$ then $nQ\ge(m+2)Q\ge mQ+2$, so
$a=nQ+R\ge mQ+R+2\ge mQ+\min(m,R)+2$.
\end{proof}

\section{The lower bound}

\begin{theorem}[Lower bound]\label{thm:lower}
Let $n\ge m+2$ and $r=\frac{m(m+3)}{2}$.  Then $r(m\cdot\one)\ge r$ on $K_n$.
\end{theorem}

\begin{proof}
Let $E\ge0$ be effective with $\deg E=r$; write $A(v)=E(v)\in\ZZ_{\ge0}$, so
$\sum_vA(v)=r$.  We must produce $f$ with $m\cdot\one-E+Lf\ge0$.

\emph{Case 1: $A(v)\le m$ for all $v$.}  Then $m\cdot\one-E\ge0$ already; take $f=0$.

\emph{Case 2: $A(v_0)\ge m+1$ for some $v_0$.}  For a threshold $t\in\{1,\dots,m\}$
define the cost $T(t)=\sum_v w\bigl(A(v),m-t\bigr)$.  By Lemma~\ref{lem:anti}, $T$ is
nondecreasing.

\emph{Step 1: some threshold pays for itself.}  Suppose $T(t)\ge t+1$ for all
$t\in\{1,\dots,m\}$.  Substituting $t=j+1$ for $j=0,\dots,m-1$ and summing,
\[
  \sum_{j=0}^{m-1}(j+2)\ \le\ \sum_{j=0}^{m-1}T(j+1)
  =\sum_v\sum_{j=0}^{m-1}w\bigl(A(v),m-1-j\bigr)
  =\sum_v\sum_{j=0}^{m-1}w\bigl(A(v),j\bigr),
\]
the last step being the reflection $j\mapsto m-1-j$.  By Corollary~\ref{cor:count} the
right side is at most $\sum_vA(v)=r$, and strictly less because $A(v_0)\ge m+1$.  But the
left side equals $\frac{m(m-1)}{2}+2m=\frac{m(m+3)}{2}=r$, so $r<r$, a contradiction.
Hence some $t\in\{1,\dots,m\}$ has $T(t)\le t$.

\emph{Step 2: the least such threshold is a fixed point.}  Let $t$ be minimal with
$T(t)\le t$.  If $t=1$ then $w(A(v_0),m-1)\ge1$ (as $A(v_0)\ge m+1>m-1$), so $T(1)\ge1$
and thus $T(1)=1$.  If $t\ge2$ then minimality gives $T(t-1)\ge t$ and monotonicity gives
$T(t-1)\le T(t)\le t$, so $T(t)=t$.

\emph{Step 3: the firing vector.}  Put $f(v)=w\bigl(A(v),m-t\bigr)-1$, so
$\sum_uf(u)=T(t)-n=t-n$.  By Lemma~\ref{lem:lap}, for each $v$,
\[
  \bigl(m\cdot\one-E+Lf\bigr)(v)=m-A(v)+n\,f(v)-(t-n)
  =m-A(v)+n\,w\bigl(A(v),m-t\bigr)-t,
\]
which by Lemma~\ref{lem:defprop} (with $j=m-t$) is at least $m-(m-t)-t=0$.
\end{proof}

\begin{remark}
The two ``one-shot'' strategies in the literature fire the complement of a single set
$\{v:E(v)\ge t\}$, and their yield is $\min(3m-1,k+m)$ and
$\min(2m+\lfloor m^2/4\rfloor,\,k+m)$ respectively, where $k$ is the minimum degree.  On
$K_n$ with $n$ large the cap $k+m$ is irrelevant, and Theorem~\ref{thm:lower} beats both
as soon as $m\ge3$.  The reason is visible in the proof: the winning $f$ takes many
distinct values, whereas a set firing takes only two.
\end{remark}

\begin{remark}
Steps 1--3 constitute an algorithm: compute $T(1),T(2),\dots$ until $T(t)\le t$ and
output $f$.  Each evaluation of $T$ costs $O(n)$, so the algorithm runs in $O(nm)$ time
and produces a certified firing vector.
\end{remark}

\section{The upper bound and the Main Theorem}

\begin{theorem}[Staircase obstruction]\label{thm:upper}
Let $n\ge m+2$ and $r=\frac{m(m+3)}{2}$.  Then $r(m\cdot\one)\le r$ on $K_n$.
\end{theorem}

\begin{proof}
Consider the effective staircase test divisor
\[
  E^\ast=\bigl(m+1,\ m,\ m-1,\ \dots,\ 1,\ 0,\ \underbrace{0,\dots,0}_{n-m-2}\bigr),
\]
of degree $(m+1)+\sum_{j=0}^{m}j=\frac{m(m+3)}{2}+1=r+1$.  Subtracting,
$m\cdot\one-E^\ast$ has value $-1$ at $v_1$, value $i-2$ at $v_i$ for $2\le i\le m+2$,
and value $m$ elsewhere: precisely the staircase divisor $S_{n,m}$ of
Definition~\ref{def:stair}.  By Proposition~\ref{prop:stuck}, $d(S_{n,m})=1>0$, so
$m\cdot\one-E^\ast$ is not equivalent to an effective divisor, witnessing
$r(m\cdot\one)<r+1$.
\end{proof}

\begin{theorem}[Main Theorem]\label{thm:main}
For $n\ge m+2$, on the complete graph $K_n$,
\[
  r(m\cdot\one)=\frac{m(m+3)}{2},
\]
independently of $n$.
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:lower} and \ref{thm:upper}.
\end{proof}

\begin{corollary}[Riemann--Roch consistency]\label{cor:rrc}
On $K_n$ the residual of $m\cdot\one$ is $(n-3-m)\cdot\one$, uniform again.  For
$0\le m\le n-3$ Theorem~\ref{thm:main} applies to both, and Riemann--Roch reads
\[
  \frac{m(m+3)}{2}-\frac{(n-3-m)(n-m)}{2}=mn-\frac{(n-1)(n-2)}{2}+1 ,
\]
an identity verified by expansion.  Equivalently, the upper and lower bounds of
Theorem~\ref{thm:main} are exchanged by $m\leftrightarrow n-3-m$: for $m\le n-3$ either
half implies the other.  For $m=n-2$ the residual is $(-1)\cdot\one$, of rank $-1$, and
Riemann--Roch gives $r=mn-g=\frac{m(m+3)}{2}$ directly.
\end{corollary}

\begin{proof}
Put $M=n-3-m$, so $m+M=n-3$.  Then
\[
  \frac{m^2+3m}{2}-\frac{M^2+3M}{2}=\frac{(m-M)(m+M+3)}{2}=\frac{(2m-n+3)n}{2}
  =mn-\frac{n^2-3n}{2},
\]
while $mn-\frac{(n-1)(n-2)}{2}+1=mn-\frac{n^2-3n}{2}$.
\end{proof}

\begin{corollary}[One-shot firing is insufficient]\label{cor:oneshot}
For $m\ge3$ and $n\ge m+2$,
\[
  r(m\cdot\one)=\frac{m(m+3)}{2}>2m+\Bigl\lfloor\frac{m^2}{4}\Bigr\rfloor\ \ge\ 3m-1 .
\]
\end{corollary}

\begin{proof}
$\frac{m^2+3m}{2}-2m-\frac{m^2}{4}=\frac{m(m-2)}{4}>0$ for $m\ge3$; the floor only helps.
\end{proof}

