\section{Algorithms}\label{sec:alg}

\subsection{Deciding the dollar game in linear time}

By Lemma~\ref{lem:per}, $\varphi_D$ is $n$-periodic with increments determined by the
residue histogram of $D$:

\begin{quote}
\textbf{Input:} $D\in\ZZ^n$.
\begin{enumerate}
\item $c[j]\leftarrow\#\{v: D(v)\equiv j \pmod n\}$ for $j=0,\dots,n-1$.
\item $s_0\leftarrow\min_vD(v)$;\quad
      $\phi\leftarrow\sum_v\lceil (s_0-D(v))/n\rceil-s_0$;\quad
      $\mathrm{best}\leftarrow\phi$.
\item For $s=s_0,\dots,s_0+n-1$: $\phi\leftarrow\phi+c[s\bmod n]-1$;
      $\mathrm{best}\leftarrow\min(\mathrm{best},\phi)$.
\item Return $\mathrm{best}=d(D)$;\ \ $D\sim$ effective iff $\mathrm{best}\le0$.
\end{enumerate}
\end{quote}

\begin{proposition}
The algorithm returns $d(D)$ in $O(n)$ arithmetic operations.
\end{proposition}

\subsection{Constructing a winning firing vector}

Given $m\cdot\one$ on $K_n$ ($n\ge m+2$) and any effective $E$ with
$\deg E\le\frac{m(m+3)}{2}$, the proof of Theorem~\ref{thm:lower} is an algorithm:
if $E(v)\le m$ for all $v$ return $f=0$; otherwise, for $t=1,2,\dots,m$ compute
$T=\sum_v\lceil (E(v)-(m-t))/n\rceil_+$ and, as soon as $T\le t$, return
$f(v)=\lceil (E(v)-(m-t))/n\rceil_+-1$.

\begin{proposition}
The algorithm terminates, runs in $O(nm)$ time, and its output satisfies
$m\cdot\one-E+Lf\ge0$.
\end{proposition}

\subsection{Computing ranks exactly}

Since $r(D)+1$ is the least degree of an effective $E$ with $D-E\not\sim$ effective, and
effectivity is decidable in $O(n)$, the exact rank of any divisor on $K_n$ can be
computed by enumerating effective test divisors in order of degree.  The enumeration is
exponential in general but entirely practical for small $n$, and was used to verify all
exact values reported here.

\section{Theta characteristics and Brill--Noether specialty}

\begin{theorem}[Half-canonical theta characteristic on $K_{2m+3}$]\label{thm:theta}
Let $n=2m+3$ with $m\ge0$.  On $K_n$:
\begin{enumerate}
\item $K_{K_n}=(n-3)\one=2m\cdot\one=2\,(m\cdot\one)$, so $m\cdot\one$ is a theta
characteristic (indeed $2D=K$ on the nose);
\item $\deg(m\cdot\one)=m(2m+3)=g(K_n)-1$;
\item $r(m\cdot\one)=\frac{m(m+3)}{2}$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) is immediate from $K_{K_n}(v)=n-3=2m$.  For (2),
$g=\frac{(2m+2)(2m+1)}{2}=2m^2+3m+1$ while $\deg(m\cdot\one)=2m^2+3m=g-1$.  (3) is
Theorem~\ref{thm:main}, applicable since $2m+3\ge m+2$.
\end{proof}

\begin{corollary}\label{cor:beat}
$K_{2m+3}$ is $k$-regular with $k=2m+2$.  A general theorem guarantees that every simple
$k$-regular graph with $k\ge6$, $k\ne7$, carries a divisor of degree $g-1$ and rank at
least $k-1$.  On $K_{2m+3}$ the witness of Theorem~\ref{thm:theta} has rank
$\frac{m(m+3)}{2}$, and
\[
  \frac{m(m+3)}{2}\ge 2m+1=k-1\ (m\ge2),\qquad \frac{m(m+3)}{2}>k-1\ (m\ge3),
\]
since $\frac{m^2+3m}{2}-(2m+1)=\frac{(m-2)(m+1)}{2}$.  Equality holds exactly at $m=2$,
i.e.\ on $K_7$, where the rank is $5=k-1$.
\end{corollary}

\begin{corollary}[A quarter of the genus]\label{cor:quarter}
With $n=2m+3$, $g=2m^2+3m+1$ and $r=\frac{m^2+3m}{2}$, one has $4r-g=3m-1>0$ for
$m\ge1$; thus $r>g/4$.
\end{corollary}

\begin{discussion}
For a Brill--Noether general object of genus $g$, the expected dimension of the family of
degree-$d$ classes of rank $\ge r$ is $\rho=g-(r+1)(g-d+r)$, and classes of rank $\ge r$
exist only when $\rho\ge0$.  At $d=g-1$ this reads $\rho=g-(r+1)^2\ge0$, i.e.\
$r\le\sqrt g-1$.  Corollary~\ref{cor:quarter} says complete graphs have half-canonical
rank $>g/4$, exceeding $\sqrt g-1$ by an unbounded factor.  Complete graphs are thus
extremal specimens of Brill--Noether \emph{special} behaviour --- the opposite of the
generic regime in which the tropical proof of the Brill--Noether theorem \cite{CDPR}
operates.
\end{discussion}

\begin{remark}
For $n$ even, $K_{K_n}=(n-3)\one$ has odd constant value, so no uniform divisor is half of
it, and the natural half-canonical witnesses are non-uniform: take $\lfloor
(n-3)/2\rfloor$ chips at every vertex and dump the leftover degree on one vertex.  On
$K_6$ ($k=5$, $g=10$) this gives $(4,1,1,1,1,1)$ of degree $9=g-1$, whose rank is exactly
$2$, well short of $k-1=4$; on $K_8$ ($k=7$, $g=21$) it gives $(6,2,2,2,2,2,2,2)$ of
degree $20=g-1$, whose rank is exactly $5=k-2$.
\end{remark}

